export function CandleCanvas({series=[]}){
 const data=series.slice(-48).filter(x=>Number.isFinite(x.price)&&x.price>0),w=960,h=272;
 if(data.length<2)return <p className="muted">Select a symbol to display price history.</p>;
 const lows=data.map(x=>Number(x.low)||x.price),highs=data.map(x=>Number(x.high)||x.price);
 const bottom=Math.min(...lows)*.995,top=Math.max(...highs)*1.005,dy=Math.max(.001,top-bottom);const y=p=>22+(top-p)/dy*(h-52),dx=(w-70)/data.length;
 return <div className="pro-candle-wrap"><svg role="img" aria-label="Historical OHLC price chart" viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="xMidYMid meet"><defs><linearGradient id="candleBG" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#13243c"/><stop offset="1" stopColor="#0c1729"/></linearGradient></defs><rect x="0" y="0" width={w} height={h} rx="14" fill="url(#candleBG)"/>{Array.from({length:5},(_,i)=><g key={i}><line x1="16" x2="905" y1={23+i*(h-54)/4} y2={23+i*(h-54)/4} stroke="#2b3d55" strokeDasharray="4 6"/><text x="914" y={27+i*(h-54)/4} fontSize="11" fill="#91a4ba">{(top-i*dy/4).toFixed(0)}</text></g>)}{data.map((x,i)=>{const o=Number(x.open)||data[Math.max(0,i-1)].price,c=x.price,hi=Number(x.high)||Math.max(o,c),lo=Number(x.low)||Math.min(o,c),up=c>=o,clr=up?'#45dbb4':'#f27794',cx=15+(i+.5)*dx;return <g key={x.date+i}><line x1={cx} x2={cx} y1={y(hi)} y2={y(lo)} stroke={clr} strokeWidth="1.8"/><rect x={cx-Math.max(2,dx*.26)} y={Math.min(y(o),y(c))} width={Math.max(4,dx*.52)} height={Math.max(1.6,Math.abs(y(o)-y(c)))} fill={clr} rx="1.5"/><title>{x.date} | O {o.toFixed(2)} H {hi.toFixed(2)} L {lo.toFixed(2)} C {c.toFixed(2)}</title></g>})}{data.filter((_,i)=>i%Math.max(1,Math.floor(data.length/6))===0).map((x,i)=><text key={i} x={22+i*(w-120)/6} y={h-7} fill="#879db6" fontSize="11">{x.date.slice(5)}</text>)}</svg><p className="pro-chart-caption">Historical daily OHLC when available; public feeds may be delayed. Do not treat charts as trade signals.</p></div>;
}
