 const importBroker=async()=>{if(!window.confirm('Read your consented Upstox holdings from this local server and replace the current stock positions?'))return;try{setErr('Reading authenticated brokerage holdings…');const r=await fetch('/api/broker/stocks');const d=await r.json();if(!r.ok)throw new Error(d.error||'Import unavailable');const recognized=d.items.filter(a=>quotes.some(q=>q.symbol===a.symbol));if(!recognized.length)throw new Error('None of the imported NSE symbols are in the current market catalog. Add them via Markets first.');setHoldings(recognized.map(x=>({id:crypto.randomUUID(),symbol:x.symbol,qty:x.qty,avg:x.avg,sector:quotes.find(q=>q.symbol===x.symbol)?.sector||'Other'})));setErr(`Imported ${recognized.length} positions (of ${d.items.length}). Other tickers can be added in Markets.`)}catch(e){setErr(e.message)}};
